package dev.aurora.client.gui.menu;

import com.mojang.blaze3d.systems.RenderSystem;
import dev.aurora.client.AuroraClient;
import dev.aurora.client.gui.ui.Ui;
import dev.aurora.client.gui.ui.UiFont;
import dev.aurora.client.util.ColorUtil;
import net.minecraft.client.MinecraftClient;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.texture.NativeImage;
import net.minecraft.client.texture.NativeImageBackedTexture;
import net.minecraft.util.Identifier;

import java.io.InputStream;

/**
 * The Aurora logo (generated by tools/LogoGenerator.java): the emblem, the mod icon and the "AURORA" wordmark. The
 * images are read straight from the mod jar into dynamic textures with smooth filtering, so they can also be drawn on
 * the loading overlay while resource packs reload.
 */
public final class AuroraLogo {
    private static final Identifier EMBLEM = Identifier.of(AuroraClient.MOD_ID, "dynamic/logo_emblem");
    private static final Identifier ICON = Identifier.of(AuroraClient.MOD_ID, "dynamic/logo_icon");
    private static final int EMBLEM_SIZE = 256;
    private static final int ICON_SIZE = 128;
    private static int state; // 0 not loaded, 1 loaded, -1 failed

    private AuroraLogo() {
    }

    private static boolean ensureLoaded() {
        if (state != 0) return state > 0;
        RenderSystem.assertOnRenderThread();
        try {
            register(EMBLEM, "/assets/aurora/textures/gui/logo.png");
            register(ICON, "/assets/aurora/icon.png");
            state = 1;
        } catch (Exception e) {
            AuroraClient.LOGGER.warn("Could not load the Aurora logo", e);
            state = -1;
        }
        return state > 0;
    }

    private static void register(Identifier id, String path) throws Exception {
        try (InputStream in = AuroraLogo.class.getResourceAsStream(path)) {
            if (in == null) throw new IllegalStateException(path + " missing");
            NativeImageBackedTexture texture = new NativeImageBackedTexture(NativeImage.read(in));
            MinecraftClient.getInstance().getTextureManager().registerTexture(id, texture);
            texture.setFilter(true, false); // smooth when drawn smaller than the image
        }
    }

    /** The emblem (transparent background) as a square of {@code size} at (x, y). */
    public static void emblem(DrawContext ctx, int x, int y, int size) {
        if (!ensureLoaded()) return;
        RenderSystem.enableBlend();
        ctx.drawTexture(EMBLEM, x, y, size, size, 0, 0, EMBLEM_SIZE, EMBLEM_SIZE, EMBLEM_SIZE, EMBLEM_SIZE);
    }

    /** The mod icon (emblem on a dark rounded square). */
    public static void icon(DrawContext ctx, int x, int y, int size) {
        if (!ensureLoaded()) return;
        RenderSystem.enableBlend();
        ctx.drawTexture(ICON, x, y, size, size, 0, 0, ICON_SIZE, ICON_SIZE, ICON_SIZE, ICON_SIZE);
    }

    /**
     * Emblem above the letter-spaced "AURORA" wordmark, centred on {@code centerX} with its top at {@code y}.
     *
     * @return the total height
     */
    public static int draw(DrawContext ctx, int centerX, int y, int emblemSize, float alpha) {
        RenderSystem.setShaderColor(1, 1, 1, alpha);
        emblem(ctx, centerX - emblemSize / 2, y, emblemSize);
        RenderSystem.setShaderColor(1, 1, 1, 1);
        float scale = 2f;
        String word = "AURORA";
        float spacing = 3;
        float wordW = 0;
        for (int i = 0; i < word.length(); i++) wordW += UiFont.width(word.substring(i, i + 1), UiFont.Size.TITLE, true) + (i < word.length() - 1 ? spacing : 0);
        float wordY = y + emblemSize + 4;
        ctx.getMatrices().push();
        ctx.getMatrices().translate(centerX - wordW * scale / 2f, wordY, 0);
        ctx.getMatrices().scale(scale, scale, 1);
        float cx = 0;
        int alphaByte = Math.max(4, Math.round(255 * alpha));
        for (int i = 0; i < word.length(); i++) {
            String ch = word.substring(i, i + 1);
            float t = i / (float) (word.length() - 1);
            float wave = (float) (0.5 + 0.5 * Math.sin(System.currentTimeMillis() / 900.0 - i * 0.5));
            int color = ColorUtil.lerp(ColorUtil.lerp(0xFF7DE3F4, 0xFFC4B5FD, t), 0xFFFFFFFF, wave * 0.35f);
            UiFont.draw(ctx, ch, cx, 0, ColorUtil.withAlpha(color, alphaByte), UiFont.Size.TITLE, true);
            cx += UiFont.width(ch, UiFont.Size.TITLE, true) + spacing;
        }
        ctx.getMatrices().pop();
        return emblemSize + 4 + Math.round(UiFont.height(UiFont.Size.TITLE) * scale);
    }

    /** Text color for secondary lines under the logo. */
    public static int subtitleColor() {
        return Ui.SUBTEXT;
    }
}
